INSERT INTO public.sgc_casos VALUES (3090, '2024-06-19', '6972894', 'FEDERICO', 'CARDOZO', '04144290835', 'No Aplica', 1, 3, 18, 7, 83, 287, 2, 'buenas tardes estimados , saludos cordiales . somos la empresa valpacking, c.a rif J-30721541-0 nuestro  nro de registro : P342090. la presente solicitamos saber como va nuestro proceso de solicitud de COPIA CERTIFICADA DE NUESTRO REGISTRO . la misma se realiza hace mas de 2 meses sin ninguna respuesta . el 30/05 nuevamente nos dirigimos hasta sus oficina en caracas y conversamos con los señores RAMON MESA y otro sr llamado DAVID ellos nos sugirieron realizar nueva mente la carta de solicitud y nos la recibieron ese día, hasta la fecha no hemos tenido ninguna información. ya por este medio hemos pasado quejas 3 veces y por vía whassap nos hemos comunicados siendo la única respuesta (Ya se direccionó al departamento encargado y Lo que les indican en taquilla es que aún no están listos) dependemos de ese requisito para continuar con otros proceso y estamos paralizados ... le agradezco su colaboración en prestarnos su apoyo se despide sr federico cardozo gerente.', 4, 1, NULL, false, 1, 'No aplica', 'valpacking2@gmail.com', 1, '14:04:35 PM', NULL, NULL, NULL, NULL);
