INSERT INTO public.sgc_casos VALUES (3999, '2024-07-15', '11618357', 'JOSE HELIBERTO', 'SEGOBIA BARRIOS', '04126741730', 'No Aplica', 2, 3, 18, 12, 135, 429, 2, 'En fecha 02 de marzo de 2023, se solicita a nombre de mi mandante el registro de la marca Vaina Loca, inscripción: 2023-1702, en clase 33 Internacional. Siendo publicada como solicitada en el Boletín 624, terminando el lapso para oposiciones el 20 de noviembre de 2023, sin que haya tenido oposición. A la fecha nos encontramos en espera de que se realice el Examen de Fondo, que presenta un retraso considerable en comparación con otras solicitudes presentadas posteriormente que ya fueron analizadas. Por ende, solicitamos se tome en cuenta esto y se de continuidad al tramite administrativo que lleva ocho meses en espera de Examen de Fondo. Sin mas nada que agregar, nos despedimos esperando su oportuna respuesta. ', 6, 1, NULL, false, 1, 'No aplica', 'josehsegobiab@gmail.com', 1, '12:00:49 PM', NULL, NULL, NULL, NULL);
