INSERT INTO public.sgc_casos VALUES (568, '2024-04-16', '7441405', 'PABLO ARTURO', 'TERAN', '04126235014', 'No Aplica', 2, 3, 18, 14, 174, 602, 2, 'EN EL BOLETIN 629 FUE DECLARADA LA SOLICITUD 2020-6647 COMO RATIFICACION PRIORIDAD EXTINGUIDA TOMO XVII  PAGINA 77. ES IMPORTANTE SEÑALAR QUE EL 14/01/2022 SE PRESENTO UN ESCRITO DE RECONSIDERACION A PRIORIDAD EXTINGUIDA SEGUN CONTEMPLA LA LEY DE PROPIEDAD INDUSTRIAL EN ESTOS CASOS CUANDO EN EL BOLETIN 613 SE DECLARA LA MISMA POR NO HABERSE AJUSTADO A LOS REQUISITOS EXIGIDOS POR ESE DESPACHO, SUBSANANDO EL ERROR Y PRESENTANDOSE UNANUEVAY CORRECTA DESCRIPCION DE LA ETIQUETA (VER ANEXO). POR LO ANTES EXPUESTO SOLICITO MUY RESPETUOSAMENTE SEA TOMADO EN CONSIDERACION ESTE RECURSO PRESENTADO OPORTUNAMENTE YA QUE EN EL BOLETIN 624 FUE CONCEDIDA LA SOLICITUD NRO 2023-3748 SANNET SOLUTIONS SIN TOMAR EN CUENTA LA PRIORIDAD QUE POSEO SOBRE ESTE NOMBRE. AGRADEZCO SUS BUENOS OFICIOS Y LA PRONTA RESPUESTA QUE PUEDAN DAR A ESTA PETICION', 6, 1, 'V', false, 1, 'No aplica', 'ivette.contreras@sannet.com.ve', 1, '09:34:05 AM', NULL, NULL, NULL, NULL);
