INSERT INTO public.sgc_casos VALUES (15924, '2025-02-20', '25624443', 'YISMAR', 'GARCIA', '04127090128', 'No Aplica', 1, 3, 18, 24, 1, 17, 2, 'Solicitud de carga en el sistema WEBPI del Registro: La marca de mi representada fue concedida en el año 1955 y le fue asignado por el Ministerio de Fomento como número de registro el siguiente 30.400-F, es el caso que la marca vence este año 2025 y debemos presentar la solicitud de renovación dentro del tiempo legal oportuno. Ahora bien, el registro 30.400-F de mi representada no ha sido incluido en el sistema WEBPI-SAPI, al agregar este registro el sistema indica que no tiene datos asociados, fue presentado un escrito en fecha 20/01/2025 solicitando la inclusión del registro y a la fecha aún esto no ha ocurrido, con lo cual no podremos presentar la renovación una vez se abra el lapso legal para hacerlo (mes de abril). En consecuencia, realizo la petición por este medio a fin de que el registro 30.400-F sea debidamente incluido en el sistema en línea WEBPI.   ', 6, 2, 'V', false, 1, 'No aplica', 'ygarcia@moreaugonzalez.com', 1, '13:16:20 PM', 27, '1997-08-14', 'Abogada', NULL);
