INSERT INTO public.sgc_casos VALUES (4461, '2024-07-23', '13888642', 'AURELIO', 'ANTONACCI', '04127249347', 'No Aplica', 2, 3, 18, 24, 1, 2, 2, 'Solicito respetuosamente agilizar el registro de mi marca HASAKI la cual hemos esperado pacientemente por casi 1 año y medio. Entiendo que todo tiene su proceso, pero considero ya ha pasado un tiempo prudente.  En fecha 29/03/2023 ingrese la solicitud 2023-002631 por el registro de la marca HASAKI.  Siete meses despues un Oficio de Devolucion, el cual fue contestado oportunamente el 17/11/23. Seguimos esperando hasta el 02/04/2023 que introducimos escrito de agilizacion. A la fecha de hoy 23/07/2024 aun no recibimos respuesta oportuna sobre el registro de esta marca.', 4, 1, 'V', false, 1, 'No aplica', 'investorgroupvzla@gmail.com', 1, '17:38:45 PM', NULL, NULL, NULL, NULL);
