INSERT INTO public.sgc_casos VALUES (360, '2024-04-11', '15328660', 'WILDYS ', 'ANDARA', '04129176924', 'No Aplica', 1, 3, 18, 14, 173, 600, 2, 'Desde hace 5 años realicé la solicitud de la copia del certificado de registro y la copia del ejemplar de la obra. Me fue entregada la copia del certificado, y aún a estas alturas, después de casi 5 años, no he recibido la copia del ejemplar de la obra. Me han dicho que la están buscando y que no aparece. He ido varias veces y siempre me dicen lo mismo. Es una falta de respeto a mi integridad como creador, puesto que presumo plagio de la obra, y aun no he podido tener la copia del ejemplar en mis manos para poder comprobarlo. ', 5, 2, 'V', false, 1, 'No aplica', 'wasoylarosa@gmail.com', 1, '12:52:14 PM', 44, '1980-12-20', '', NULL);
